create or replace function public.transition_marketplace_order(p_order_id uuid,p_expected_version bigint,p_to_state text,p_actor_user_id uuid,p_actor_org_id uuid default null,p_idempotency_key text default null,p_reason text default null) returns public.marketplace_orders language plpgsql security definer set search_path='' as $$ declare r public.marketplace_orders; old_state text; new_version bigint; begin if p_to_state not in ('payment_pending','paid','fulfillment','complete','refund_requested','refunded','dispute') then raise exception 'invalid order state'; end if; if p_idempotency_key is not null and exists (select 1 from public.marketplace_order_state_events e where e.order_id=p_order_id and e.idempotency_key=p_idempotency_key) then select * into r from public.marketplace_orders where id=p_order_id; return r; end if; select order_state,state_version into old_state,new_version from public.marketplace_orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if; if new_version <> p_expected_version then raise exception 'stale order version'; end if; if old_state=p_to_state then raise exception 'duplicate order transition without idempotency key'; end if; if p_actor_org_id is not null and not exists (select 1 from public.marketplace_memberships m where m.organization_id=p_actor_org_id and m.user_id=p_actor_user_id and m.status='active' and m.role in ('owner','admin','buyer','seller','moderator','operator')) then raise exception 'actor not authorized for order organization'; end if; update public.marketplace_orders set order_state=p_to_state,state_version=state_version+1,state_updated_at=now(),state_updated_by=p_actor_user_id where id=p_order_id returning * into r; insert into public.marketplace_order_state_events(order_id,from_state,to_state,state_version,actor_user_id,actor_organization_id,idempotency_key,reason) values(p_order_id,old_state,p_to_state,r.state_version,p_actor_user_id,p_actor_org_id,p_idempotency_key,p_reason); return r; end; $$;
revoke execute on function public.transition_marketplace_order(uuid,bigint,text,uuid,uuid,text,text) from public,anon;
grant execute on function public.transition_marketplace_order(uuid,bigint,text,uuid,uuid,text,text) to authenticated,service_role;
